<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Services\Marketing\MarketingPostCaption;
class MarketingCaptionTest extends TestCase {
 public function test_every_content_type_has_distinct_copy_structure(){ $s=app(MarketingPostCaption::class);$rules=[];foreach(\App\Services\Marketing\MarketingFreePosts::TYPES as $type)$rules[]=$s->strategy($type);$this->assertCount(9,array_unique($rules));$this->assertStringContainsString('checklist',$s->strategy('checklist'));$this->assertStringContainsString('story',$s->strategy('storytelling'));}
 public function test_checklist_fallback_has_paragraphs_points_and_server_owned_facebook_destination(){config(['marketing.caption_public_origin'=>'https://shop.example']);$s=app(MarketingPostCaption::class);$target=$s->destination('real-product');$text=$s->complete('Meet our product. Share your requirements. Confirm details by quotation.','checklist','facebook',$target,'English');$this->assertStringContainsString("\n\n",$text);$this->assertStringContainsString("\n• ",$text);$this->assertStringContainsString('https://shop.example/products/real-product',$text);}
 public function test_profile_platforms_do_not_promise_clickable_caption_links_or_configured_bio(){config(['marketing.caption_public_origin'=>'https://shop.example']);$s=app(MarketingPostCaption::class);foreach(['instagram','tiktok'] as $platform){$text=$s->complete("A clear hook.\n\nUseful details.",'poster',$platform,$s->destination('lamp'),'English');$this->assertStringNotContainsString('https://',$text);$this->assertStringContainsString('profile',$text);$this->assertSame('profile_link_setup_required',$s->cta('lamp',$platform)['delivery']);}}
 public function test_private_or_missing_origins_never_become_public_cta_links(){foreach(['http://127.0.0.1:8500','http://localhost','https://192.168.1.2','javascript:alert(1)','https://user:pass@shop.example',''] as $bad){config(['marketing.caption_public_origin'=>$bad]);$this->assertNull(app(MarketingPostCaption::class)->destination('lamp'));}}
 public function test_caption_html_preserves_text_and_only_links_http_urls_safely(){ $s=app(MarketingPostCaption::class);$html=$s->html("Hello <script>alert(1)</script>\n\nhttps://shop.example/products/lamp");$this->assertStringNotContainsString('<script>',$html);$this->assertStringContainsString('&lt;script&gt;',$html);$this->assertStringContainsString('href="https://shop.example/products/lamp"',$html);$this->assertStringContainsString("\n\n",$html);}
}
